from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    def is_valid_move(r, c):
        """Check if a move is valid, not hitting a wall and inside the grid."""
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([start])
    visited = {start}

    while queue:
        r, c = queue.popleft()
        if (r, c) == goal:
            # We found a path, build it by backtracking from the current position
            path = [(r, c)]
            current = (r, c)
            while current != start:
                for dr, dc in directions:
                    nr, nc = current[0] + dr, current[1] + dc
                    if (nr, nc) in visited and (nr, nc) in [{'up': (dr-1, dc), 'down': (dr+1, dc), 'left': (dr, dc-1), 'right': (dr, dc+1)}.get(path[-1][0] - r + c - path[-1][1], {})].values():
                        current = (nr, nc)
                        path.append(current)
                        break
            return path

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid_move(nr, nc) and (nr, nc) not in visited:
                queue.append((nr, nc))
                visited.add((nr, nc))

    return []

