def solve(grid, start, goal):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    free = lambda x, y: 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == '.'

    def dfs(x, y, Stack):
        if (x, y) == goal:
            return [Stack]
        if (x, y) in Stack:
            return []

        Stack.add((x, y))
        paths = []
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if free(nx, ny):
                path = dfs(nx, ny, Stack.copy())
                if path:
                    paths.append([*(Stack), (nx, ny)] + path[1:])
        Stack.remove((x, y))
        return paths

    if (start in ((x, y) for x, y in enumerate(grid) for row in grid if row[y] == '#')):
        return []
    if start == goal and free(*start):
        return [start]
    return dfs(*start, set())

