from collections import deque

def neighbors(cell):
    """Generate the 4 orthogonal neighbors of a cell."""
    r, c = cell
    yield (r - 1, c)  # up
    yield (r + 1, c)  # down
    yield (r, c - 1)  # left
    yield (r, c + 1)  # right

def valid(cell, grid):
    """Check if a cell is within the grid boundaries and not a wall."""
    r, c = cell
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

def solve(grid, start, goal):
    """Find a path between two cells of a grid using bidirectional BFS."""
    if start == goal:
        return [start]
    if not valid(start, grid) or not valid(goal, grid):
        return []

    moving_from_start = deque([(start, [start])])
    moving_from_goal = deque([(goal, [goal])])
    seen_from_start = set([start])
    seen_from_goal = set([goal])
    while moving_from_start or moving_from_goal:
        if moving_from_start:
            cell, path = moving_from_start.popleft()
            for neighbor in neighbors(cell):
                if valid(neighbor, grid) and neighbor not in seen_from_start:
                    seen_from_start.add(neighbor)
                    if neighbor in seen_from_goal:
                        return path + [neighbor]
                    moving_from_start.append((neighbor, path + [neighbor]))
        if moving_from_goal:
            cell, path = moving_from_goal.popleft()
            for neighbor in neighbors(cell):
                if valid(neighbor, grid) and neighbor not in seen_from_goal:
                    seen_from_goal.add(neighbor)
                    if neighbor in seen_from_start:
                        indices = sorted([i for i, p in enumerate(path + [neighbor]) if p in seen_from_start])
                        return path + [neighbor][:indices[-1] + 1] + path[indices[-1]:][::-1]
                    moving_from_goal.append((neighbor, path + [neighbor]))

    return []

