def solve(grid, start, goal):
    # Adjust start, goal, and boundary to 1-based indexing
    start = (start[0] + 1, start[1] + 1)
    goal = (goal[0] + 1, goal[1] + 1)
    boundary = lambda row, col: row < 1 or row > len(grid) or col < 1 or col > len(grid[0])

    # Convert grid to 1-based indexing
    grid = [list(row) for row in grid]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '#':
                grid[i][j] = 'X'

    # Define possible moves
    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Define heuristic function
    def heuristic(cell):
        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    # Run A* search
    open_list = [start]
    came_from = {}
    cost_so_far = {start: 1}
    while open_list:
        current = min(open_list, key=lambda cell: cost_so_far[cell] + heuristic(cell))
        open_list.remove(current)
        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            return path[::-1]

        for move in moves:
            neighbor = (current[0] + move[0], current[1] + move[1])
            if boundary(*neighbor) or grid[neighbor[0] - 1][neighbor[1] - 1] == 'X':
                continue
            new_cost = cost_so_far[current] + 1
            if neighbor in cost_so_far and new_cost >= cost_so_far[neighbor]:
                continue
            cost_so_far[neighbor] = new_cost
            priority = new_cost + heuristic(neighbor)
            open_list.append(neighbor)
            came_from[neighbor] = current

    return []

