def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    cost = lambda x, y: 1 if grid[x][y] == '.' else float('inf')

    def heur(x, y):
        return abs(x - goal[0]) + abs(y - goal[1])

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    pq = [(0, start, [])]
    visited = set()
    path = {}

    while pq:
        current_cost, current_node, current_path = heapq.heappop(pq)
        current_row, current_col = current_node
        current_path_node = (current_row, current_col)

        if current_node == goal:
            res = [node for node in current_path if node != current_path_node] + [current_path_node]
            return res

        if current_node in visited:
            continue

        visited.add(current_node)

        for dx, dy in directions:
            x, y = current_row + dx, current_col + dy

            if is_valid(x, y):
                new_cost = current_cost + cost(x, y)
                new_path = current_path + [current_path_node]

                if (x, y) not in path or new_cost < path[(x, y)]:
                    path[(x, y)] = new_cost
                    heapq.heappush(pq, (new_cost + heur(x, y), (x, y), new_path))

    return []

